using System;using System.IO;using System.Reflection;using System.Drawing;using System.Windows.Forms;using LoopFive;
class HardwareUiTests {
 static int n;static void A(bool b,string s){if(!b)throw new Exception(s);n++;Console.WriteLine("PASS "+s);}
 static object F(object o,string name){return o.GetType().GetField(name,BindingFlags.Instance|BindingFlags.Public|BindingFlags.NonPublic).GetValue(o);}
 static void Wheel(Control c,int amount){typeof(Control).GetMethod("OnMouseWheel",BindingFlags.Instance|BindingFlags.NonPublic).Invoke(c,new object[]{new MouseEventArgs(MouseButtons.None,0,1,1,amount)});}
 static Control Find(Control c,string text){if(c.Text==text)return c;foreach(Control child in c.Controls){Control found=Find(child,text);if(found!=null)return found;}return null;}
 [STAThread]static void Main(){Application.EnableVisualStyles();Application.SetCompatibleTextRenderingDefault(false);string path=Path.Combine(Storage.DataDirectory,"settings.json");byte[] backup=File.Exists(path)?File.ReadAllBytes(path):null;try{using(MainForm f=new MainForm()){f.Opacity=0;f.Show();Application.DoEvents();((Timer)F(f,"timer")).Stop();f.Audio.Stop();f.SetLoopView(false);ComboBox section=(ComboBox)F(f,"centerSection"),slot=(ComboBox)F(f,"centerSlot"),type=(ComboBox)F(f,"centerType");HardwareLcd lcd=(HardwareLcd)F(f,"lcd");HardwareSurface panel=(HardwareSurface)F(f,"hardware");for(int s=0;s<2;s++){section.SelectedIndex=s;ChainConfig chain=s==0?f.Engine.Config.InputFx:f.Engine.Config.TrackFx;FxBar bar=(FxBar)F(f,s==0?"inputBar":"trackBar");for(int b=0;b<4;b++){chain.Bank=b;bar.RefreshModel();for(int i=0;i<4;i++){slot.SelectedIndex=i;string expected=chain.Slots[b*4+i].Type=="ROBOT"?"CHORUS":"ROBOT";type.SelectedItem=expected;A(chain.Slots[b*4+i].Type==expected&&bar.SelectedSlot==i,"central selector edits section "+s+" bank "+b+" slot "+i);}}}A(Math.Abs((lcd.Left+lcd.Width/2)-panel.Width/2)<2,"LCD is centered over the effect selector");A(type.Top>lcd.Bottom&&type.Left>panel.Width/3&&type.Right<panel.Width*3/4,"effect type selector is below the center screen");HardwareKnob input=(HardwareKnob)F(f,"inputDial"),output=(HardwareKnob)F(f,"outputDial");input.Value=.2f;Wheel(input,120);A(Math.Abs(f.Engine.Config.InputGain-.88f)<.0001,"input rotary controls actual recording gain");output.Value=.4f;Wheel(output,-120);A(Math.Abs(f.Engine.Config.Master-.76f)<.0001,"output rotary controls actual master level");TrackStrip[] tracks=(TrackStrip[])F(f,"strips");foreach(TrackStrip track in tracks){Fader fader=(Fader)F(track,"fader");Button fx=(Button)F(track,"fx"),settings=(Button)F(track,"settings"),stop=(Button)F(track,"stop");A(fx.Top<settings.Top&&settings.Top<stop.Top&&fader.Left>settings.Right,"channel has FX / TRACK / STOP on the left and fader on the right");}
 RecordingSource.Set(f.Engine,1,1);using(TrackDialog dialog=new TrackDialog(f.Engine,1,delegate{},delegate{},delegate{})){Language.Apply(dialog);Control sourceLabel=Find(dialog,Language.T("Fuente de grabación"));A(sourceLabel!=null,"track editor exposes the recording source selector");EditorGrid sourceGrid=(EditorGrid)sourceLabel.Parent;ComboBox sourceChoice=(ComboBox)sourceGrid.GetControlFromPosition(1,sourceGrid.GetRow(sourceLabel));sourceChoice.SelectedIndex=3;A(f.Engine.Tracks[1].Config.BounceMask==4&&!f.Engine.Tracks[1].Config.InputL,"source dropdown routes track 3 into track 2");sourceChoice.SelectedIndex=0;A(f.Engine.Tracks[1].Config.BounceMask==0&&f.Engine.Tracks[1].Config.InputL,"source dropdown restores microphone input");}Control loopBefore=((TrackStrip[])F(f,"strips"))[0];Rectangle before=loopBefore.RectangleToScreen(loopBefore.ClientRectangle);((Panel)F(f,"utilityTray")).Visible=true;f.ShowMainPage(0);Application.DoEvents();A(!((Panel)F(f,"utilityTray")).Visible&&before==loopBefore.RectangleToScreen(loopBefore.ClientRectangle),"returning from Menu restores loop geometry");f.ShowOptions();A(((Panel)F(f,"optionsWorkspace")).Visible,"top-right Options remains available");f.ShowMainPage(0);f.Engine.Dirty=false;f.Close();}Console.WriteLine("TOTAL "+n+" hardware UI checks passed");}catch(Exception e){Console.WriteLine("FAIL "+e);Environment.ExitCode=1;}finally{if(backup!=null)File.WriteAllBytes(path,backup);else if(File.Exists(path))File.Delete(path);Language.Set("es");}}
}
